				check.diagnostics.push({severity:'info', code:'manifest-path-unverified', file, evidence:directory, message});
				addReason(check, tr('\u90E8\u5206\u6E05\u5355\u8DEF\u5F84\u6240\u5728\u7684\u76EE\u5F55\u65E0\u6CD5\u904D\u5386\u3002','Some configured paths are in directories that could not be scanned.'));
